+    setPushStatus(null);
+    try {
+      await invokePromise(PushCard, {
+        board: Ref.make(board),
+        card: Ref.make(card),
+      });
+      setPushStatus('Pushed to Trello');
+      setTimeout(() => setPushStatus(null), 3000);
+    } catch (error) {
+      log.catch(error);
